<template>
  <section class="human-live-content">
    <header><div><small>{{ t('玩家直播','PLAYER STREAM') }}</small><h1>{{ room.streamer?.display_name || room.title[lang] }}</h1></div><span>{{ variantLabel }}</span></header>
    <div class="content-grid" :style="{'--board-height':`${boardGeometry.height}px`}">
      <aside class="panel timing-panel">
        <div class="side-header"><div class="panel-heading"><h2>{{ t('节点用时','Milestone times') }}</h2></div><div class="timer-row"><div class="timer">{{ duration(liveElapsed) }}</div><span class="muted small">{{ number(run?.seq) }} {{ t('步','moves') }}</span></div></div>
        <div class="milestone-heading"><span>{{ t('首次达成','First reached') }}</span><span>{{ t('用时','Time') }}</span></div>
        <div class="side-body milestone-list" tabindex="0">
          <div v-for="tile in milestones" :key="tile" class="milestone" :class="{reached:run?.nodes?.[tile]!=null}"><span class="node-tile" :class="{'node-tile-large':tile>=1024,'node-tile-huge':tile>=16384}" :style="streamTileStyle(tile)">{{ tile }}</span><strong class="node-time">{{ run?.nodes?.[tile] == null ? '—' : nodeTime(run.nodes[tile]) }}</strong></div>
        </div>
      </aside>

      <main class="board-column">
        <div class="score-row"><div><small>SCORE</small><strong>{{ number(run?.score) }}</strong></div><div><small>BEST</small><strong>{{ number(Math.max(Number(run?.best_score || 0), Number(run?.score || 0))) }}</strong></div></div>
        <div class="live-mode-row"><span>{{ t('实时对局','LIVE GAME') }}</span><strong>{{ variantLabel }}</strong></div>
        <div class="board-stage"><div class="board-wrap" :style="boardStyle"><HumanBoard :board="run?.board || emptyBoard" :rows="rows" :cols="cols" :transition="transition" :animate="true" :palette="boardAppearance"><template #overlay><div v-if="streamState !== 'live' || run?.ended_at" class="offline"><b>{{ run?.ended_at ? t('本局结束','Game over') : streamState === 'loading' ? t('正在连接','Connecting') : t('等待主播','Waiting for streamer') }}</b></div></template></HumanBoard></div></div>
      </main>

      <aside class="panel ranking-panel">
        <div class="side-header"><div class="panel-heading"><h2>{{ t('排行榜','Leaderboard') }}</h2></div><div class="period-tabs"><button :class="{active:period==='all'}" @click="setPeriod('all')">{{ t('总榜','All') }}</button><button :class="{active:period==='week'}" @click="setPeriod('week')">{{ t('近7天','7 days') }}</button></div></div>
        <div class="rank-table-heading"><span>{{ t('排名 / 玩家','Rank / player') }}</span><span>{{ t('分数','Score') }}</span></div>
        <div class="side-body ranking-body" tabindex="0"><div class="rank-list" :class="{loading:leaderLoading}">
          <div v-for="(item,index) in leaderRows" :key="item?.id || `empty-${index}`" class="rank-row" :class="{placeholder:!item}"><span class="rank-number" :class="{podium:item?.rank<=3}">{{ item?.rank || '-' }}</span><template v-if="item"><a class="rank-name" :title="item.display_name" :href="playerUrl(item)"><strong>{{ item.display_name }}</strong></a><a class="rank-score" :class="{disabled:!item.has_replay}" :href="replayUrl(item)">{{ number(item.score) }}</a></template></div>
          <div class="rank-row own-rank" :class="{placeholder:!ownLeader}"><span class="rank-number" :class="{podium:ownLeader?.rank<=3}">{{ ownLeader?.rank || '-' }}</span><template v-if="ownLeader"><a class="rank-name" :title="ownLeader.display_name" :href="playerUrl(ownLeader)"><strong>{{ ownLeader.display_name }}</strong></a><a class="rank-score" :class="{disabled:!ownLeader.has_replay}" :href="replayUrl(ownLeader)">{{ number(ownLeader.score) }}</a></template></div>
        </div><div v-if="leaderLoading || leaderError" class="ranking-status"><span>{{ leaderLoading ? t('正在读取榜单…','Loading…') : t('榜单暂不可用','Leaderboard unavailable') }}</span><button v-if="leaderError" @click="loadLeaderboard">{{ t('重试','Retry') }}</button></div></div>
      </aside>
    </div>
  </section>
</template>
<script setup>
import { ref, computed, onMounted, onUnmounted } from 'vue';
import HumanBoard from '../../human/HumanBoard.vue';
import { NODE_TILES, move } from '../../human/engine.js';
import { nodeTime } from '../../human/practice.js';
import { liveAppearanceTileStyle } from '../../human/liveAppearance.js';
import { useRoom } from '../roomContext.js';
import { liveEmptyTileColors, liveTileColors } from '../tilePalette.js';
import { humanLiveBoardGeometry, humanLiveVisibleNodeCount } from './humanBoardGeometry.js';
const props=defineProps({lang:String,streamState:String,pipActive:Boolean});
const {room}=useRoom(); const run=ref(null),transition=ref(null),clock=ref(Date.now()),receivedAt=ref(Date.now());
const period=ref('all'),leaders=ref([]),ownLeader=ref(null),leaderLoading=ref(false),leaderError=ref(false);
let leaderboardSerial=0,leaderboardVariant='',clockTimer;
const dims=computed(()=>[run.value?.rows||({'4x4':4,'3x4':3,'2x4':2,'3x3':3}[room.variant]||4),run.value?.cols||({'3x3':3}[room.variant]||4)]);
const rows=computed(()=>dims.value[0]),cols=computed(()=>dims.value[1]),variantLabel=computed(()=>(run.value?.variant||room.variant).replace('x',' × '));
const emptyBoard=computed(()=>Array(rows.value*cols.value).fill(0)),appearance=computed(()=>run.value?.appearance||null);
const boardAppearance=computed(()=>({
  version:appearance.value?.version||1,
  empty:liveEmptyTileColors(),
  tiles:appearance.value?.tiles||{},
}));
const boardGeometry=computed(()=>humanLiveBoardGeometry(rows.value,cols.value));
const boardStyle=computed(()=>({width:`${boardGeometry.value.width}px`,height:`${boardGeometry.value.height}px`}));
const milestones=computed(()=>{const count=humanLiveVisibleNodeCount(boardGeometry.value.height);return NODE_TILES.filter((tile,index)=>index<count||run.value?.nodes?.[tile]!=null)});
const leaderRows=computed(()=>Array.from({length:10},(_,index)=>leaders.value[index]||null));
const liveElapsed=computed(()=>Number(run.value?.elapsed_ms||0)+(run.value&&!run.value.ended_at&&props.streamState==='live'?Math.max(0,clock.value-receivedAt.value):0));
const t=(zh,en)=>props.lang==='zh'?zh:en;
const number=value=>Number(value||0).toLocaleString(props.lang==='zh'?'zh-CN':'en-US');
const duration=ms=>{const s=Math.floor(Number(ms||0)/1000);return `${String(Math.floor(s/3600)).padStart(2,'0')}:${String(Math.floor(s/60)%60).padStart(2,'0')}:${String(s%60).padStart(2,'0')}`};
const streamTileStyle=value=>liveAppearanceTileStyle(appearance.value,value)||liveTileColors(value);
const playerUrl=item=>`https://play.2048tables.online/user/${encodeURIComponent(item.display_name||'')}`;
const replayUrl=item=>item?.has_replay?`https://play.2048tables.online/#replay/${encodeURIComponent(item.id)}?step=0`:undefined;
async function loadLeaderboard(){const variant=run.value?.variant||room.variant;if(!variant)return;const serial=++leaderboardSerial;leaderLoading.value=true;leaderError.value=false;try{const response=await fetch(`/api/human/leaderboards?variant=${encodeURIComponent(variant)}&period=${period.value}&limit=10`,{cache:'no-store'});if(!response.ok)throw Error();const data=await response.json();if(serial===leaderboardSerial){leaders.value=data.entries||[];ownLeader.value=data.me||null;leaderboardVariant=variant;}}catch{if(serial===leaderboardSerial)leaderError.value=true}finally{if(serial===leaderboardSerial)leaderLoading.value=false}}
function setPeriod(value){if(period.value===value)return;period.value=value;loadLeaderboard()}
function touchClock(){receivedAt.value=Date.now();clock.value=receivedAt.value}
function receive(data){
  if(data instanceof ArrayBuffer){if(!run.value||data.byteLength!==9)throw Error('snapshot_required');const view=new DataView(data),seq=view.getUint32(0,true),delta=view.getUint32(4,true),code=view.getUint8(8);if(seq!==run.value.seq+1)throw Error('snapshot_required');const direction=code&3,moved=move(run.value.board,rows.value,cols.value,direction),index=(code>>2)&15,value=code&64?4:2;if(!moved.changed||index>=moved.board.length||moved.board[index])throw Error('snapshot_required');moved.board[index]=value;const elapsed=run.value.elapsed_ms+delta,nodes={...run.value.nodes};for(let tile=32;tile<=Math.max(...moved.board);tile*=2)nodes[tile]??=elapsed;transition.value={fromBoard:run.value.board,toBoard:moved.board,direction};run.value={...run.value,board:moved.board,score:run.value.score+moved.score,seq,elapsed_ms:elapsed,nodes};touchClock();return}
  if(data.type==='snapshot'){run.value=data.run;transition.value=null;touchClock();const variant=run.value?.variant||room.variant;if(variant&&variant!==leaderboardVariant)loadLeaderboard()}
  else if(data.type==='appearance'&&run.value)run.value={...run.value,appearance:data.appearance};
  else if(data.type==='best'&&run.value)run.value={...run.value,best_score:Math.max(Number(run.value.best_score||0),Number(run.value.score||0),Number(data.best_score||0))};
}
function resume(){transition.value=null;run.value=run.value?{...run.value,board:[...run.value.board]}:null;touchClock()}
function getPipFrame(){const current=run.value,key=`${current?.run_id}:${current?.seq}:${props.streamState}:${JSON.stringify(current?.appearance||{})}`;return{key,width:960,height:540,draw(ctx){const styles=getComputedStyle(document.documentElement);ctx.fillStyle=styles.getPropertyValue('--board-bg').trim()||'#1e293b';ctx.fillRect(0,0,960,540);ctx.fillStyle=styles.getPropertyValue('--text-main').trim()||'#fff';ctx.font='700 26px sans-serif';ctx.fillText(`${room.streamer?.display_name||'Player'} · ${number(current?.score)}`,40,46);const r=current?.rows||rows.value,c=current?.cols||cols.value,size=Math.min(430/r,600/c),ox=(960-c*size)/2,oy=70;for(let i=0;i<r*c;i++){const v=current?.board?.[i]||0,color=v?(liveAppearanceTileStyle(current?.appearance,v)||liveTileColors(v)):{background:styles.getPropertyValue('--color-empty').trim()||'rgba(15, 23, 42, 0.4)',color:styles.getPropertyValue('--text-secondary').trim()||'#94a3b8'},x=ox+(i%c)*size,y=oy+Math.floor(i/c)*size;ctx.fillStyle=color.background;ctx.fillRect(x+4,y+4,size-8,size-8);if(v){ctx.fillStyle=color.color;ctx.textAlign='center';ctx.textBaseline='middle';ctx.font=`700 ${Math.max(14,size*(v>=10000?.25:v>=1000?.32:.4))}px sans-serif`;ctx.fillText(String(v),x+size/2,y+size/2)}}}}}
onMounted(()=>{clockTimer=setInterval(()=>{clock.value=Date.now()},250)});onUnmounted(()=>clearInterval(clockTimer));
defineExpose({receive,resume,getPipFrame});
</script>
<style scoped>
.human-live-content{height:100%;box-sizing:border-box;padding:18px;color:var(--text-main);background:var(--bg-card);overflow:hidden}.human-live-content>header{height:52px;display:flex;align-items:start;justify-content:space-between}.human-live-content h1{margin:1px 0;font-size:25px}.human-live-content header small,.human-live-content header span{color:var(--text-secondary);letter-spacing:.08em}.content-grid{--board-height:500px;display:grid;grid-template-columns:minmax(0,210px) minmax(0,500px) minmax(0,273px);grid-template-rows:72px 40px var(--board-height);gap:12px 16px;justify-content:center;align-items:stretch}.panel{min-width:0}.timing-panel,.ranking-panel{display:grid;grid-row:1/4;grid-template-rows:72px 40px var(--board-height);min-height:0}.timing-panel{grid-column:1}.ranking-panel{grid-column:3}.side-header{display:grid;grid-template-rows:36px 30px;gap:6px}.panel-heading{display:flex;align-items:center;justify-content:space-between;gap:8px;padding:8px 10px;border-radius:3px;background:var(--board-bg);color:var(--text-main)}.panel-heading h2{margin:0;font-size:18px;line-height:1.2}.timer-row{display:flex;align-items:center;justify-content:space-between;padding:0 10px}.timer{margin:0;font-size:24px;font-weight:700;font-variant-numeric:tabular-nums}.small{font-size:12px}.muted{color:var(--text-secondary)}.milestone-heading,.rank-table-heading{display:flex;align-items:center;justify-content:space-between;margin:0;padding:0 10px;border-bottom:1px solid var(--border-main);color:var(--text-secondary);font-size:12px}.side-body{contain:size;min-height:0;overflow:auto;border:1px solid var(--border-main);border-radius:4px;background:color-mix(in srgb,var(--bg-main) 72%,var(--bg-card));overscroll-behavior:contain;scrollbar-width:thin}.side-body:focus-visible{outline:2px solid var(--accent);outline-offset:2px}.milestone-list{display:flex;flex-direction:column;gap:6px;padding:8px;overflow-x:hidden;overflow-y:auto}.milestone{display:grid;grid-template-columns:38px minmax(0,1fr);gap:6px;flex:0 0 38px;width:100%;height:38px;min-height:38px;align-items:stretch;color:var(--text-secondary)}.node-tile{display:grid;width:38px;height:38px;place-items:center;border-radius:3px;font-size:13px;font-weight:700}.node-tile-large{font-size:11px}.node-tile-huge{font-size:9px}.node-time{display:flex;align-items:center;justify-content:flex-end;padding:0 9px;border-radius:2px;background:var(--bg-card);font-size:14px;font-variant-numeric:tabular-nums;white-space:nowrap}.milestone.reached{color:color-mix(in srgb,#4fb27a 78%,var(--text-main))}.period-tabs{display:flex;gap:6px}.period-tabs button{flex:1;padding:6px;border:0;border-radius:3px;background:color-mix(in srgb,var(--board-bg) 62%,var(--bg-card));color:var(--text-secondary);font:inherit;font-size:12px;font-weight:700;cursor:pointer}.period-tabs button.active{background:var(--board-bg);color:var(--text-main)}.ranking-body{position:relative;overflow-x:hidden}.ranking-body .rank-list{display:flex;flex-direction:column;gap:6px;padding:8px}.rank-row{display:flex;flex:0 0 38px;height:38px;min-height:38px;align-items:stretch;gap:6px;overflow:hidden;border-radius:3px;background:var(--bg-card)}.rank-number{display:grid;width:38px;min-width:38px;flex:0 0 38px;place-items:center;border-radius:3px;background:#090909;color:#fff;font-size:16px;font-weight:700}.rank-number.podium{background:#bc9432}.rank-row:first-child .rank-number.podium{background:#d0af00}.rank-row:nth-child(2) .rank-number.podium{background:#a9a58d}.rank-name,.rank-score{display:flex;align-items:center;color:var(--text-main);text-decoration:none;line-height:18px}.rank-name{min-width:0;flex:1;overflow:hidden}.rank-name strong{width:100%;min-width:0;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;font-size:13px}.rank-score{flex:0 0 auto;justify-content:flex-end;padding:0 6px;font-size:15px;font-variant-numeric:tabular-nums;white-space:nowrap}.rank-score.disabled{pointer-events:none;color:var(--text-secondary)}.rank-row.placeholder{background:color-mix(in srgb,var(--bg-card) 42%,transparent)}.rank-row.placeholder .rank-number{background:color-mix(in srgb,#090909 52%,transparent);color:var(--text-secondary)}.own-rank{box-shadow:inset 0 0 0 1px color-mix(in srgb,var(--accent) 55%,transparent)}.ranking-status{position:absolute;inset:8px;display:flex;flex-direction:column;align-items:center;justify-content:center;gap:8px;padding:12px;border-radius:3px;background:color-mix(in srgb,var(--bg-card) 88%,transparent);color:var(--text-secondary);font-size:13px;text-align:center}.ranking-status button{padding:6px 10px;border:1px solid var(--border-main);border-radius:3px;background:var(--bg-main);color:var(--text-main)}.board-column{display:grid;grid-column:2;grid-row:1/4;grid-template-rows:72px 40px var(--board-height);gap:12px;min-width:0}.score-row{display:flex;align-items:stretch;justify-content:flex-end;gap:6px}.score-row>div{display:flex;width:144px;min-width:0;flex:0 0 144px;flex-direction:column;justify-content:center;padding:7px 8px;border-radius:3px;background:var(--board-bg);text-align:center}.score-row small{color:var(--text-secondary);font-size:12px;font-weight:700}.score-row strong{font-size:26px;line-height:1.25;font-variant-numeric:tabular-nums;white-space:nowrap}.live-mode-row{display:flex;align-items:center;justify-content:space-between;color:var(--text-secondary);font-size:13px}.live-mode-row strong{color:var(--text-main);letter-spacing:.08em}.board-stage{display:grid;width:500px;height:var(--board-height);place-items:center;margin:auto}.board-wrap{margin:auto}.board-wrap :deep(.human-board){--board-gap:10px;position:relative;width:100%;height:100%;display:grid;grid-template-columns:repeat(var(--cols),1fr);grid-template-rows:repeat(var(--rows),1fr);gap:var(--board-gap);padding:var(--board-gap);box-sizing:border-box;border-radius:10px;background:var(--color-board-bg);overflow:hidden}.board-wrap :deep(.human-board>.tile){min-width:0;min-height:0;padding:0;border:0;border-radius:4px;pointer-events:none}.board-wrap :deep(.logical-tile-label){visibility:hidden}.board-wrap :deep(.moving-tile){position:absolute;pointer-events:none;z-index:1;width:calc((100% - (var(--cols) + 1)*var(--board-gap))/var(--cols));height:calc((100% - (var(--rows) + 1)*var(--board-gap))/var(--rows));transition:top var(--human-slide-duration) ease-in-out,left var(--human-slide-duration) ease-in-out}.board-wrap :deep(.moving-tile.no-transition){transition:none}.board-wrap :deep(.moving-tile-inner){display:grid;place-items:center;width:100%;height:100%;border-radius:4px;font-weight:700;line-height:1}.board-wrap :deep(.tile-label){font-size:clamp(18px,calc(52px * var(--tile-font-scale,1)),52px);line-height:1}.board-wrap :deep(.board-overlay){position:absolute;inset:0;z-index:4;display:grid;place-items:center;pointer-events:none}.offline{padding:18px 40px;border-radius:6px;background:#0f172abb;color:#fff;font-size:22px}
</style>
